// Minimal Chart.js stub to prevent errors when CDN is unavailable
(function(global){
  if (global.Chart) return;
  function Chart(ctx, config){
    this.ctx = ctx;
    this.config = config || {};
    this.data = (config && config.data) ? JSON.parse(JSON.stringify(config.data)) : { labels: [], datasets: [] };
    this.options = (config && config.options) ? config.options : {};
  }
  Chart.prototype.update = function(){};
  Chart.prototype.destroy = function(){};
  Chart.prototype.getDatasetMeta = function(){ return {}; };
  global.Chart = Chart;
})(window);